CREATE OR REPLACE FUNCTION prevent_critical_equipment_delete()
RETURNS TRIGGER AS $$
DECLARE
    v_is_critical BOOLEAN;
BEGIN
    -- Check if the equipment being deleted is critical
    SELECT EXISTS (
        SELECT 1
        FROM "Equipment" e
        JOIN "EquipmentType" et ON e."EquipType" = et."EquipType"
        WHERE e."EQUIP_CODE" = OLD."EQUIP_CODE"
          AND e."EquipType" = 'Safety'
          AND (et."type_indices"->>'safety_idx')::numeric > 0.75
          AND (
              -- Life support or O2 supply status exists in LightingAndSafety
              EXISTS (
                  SELECT 1 FROM "LightingAndSafety" ls
                  WHERE ls."equipRef" = e."EQUIP_CODE"
                    AND (ls."lifeSupportStat" IS NOT NULL OR ls."O2SupplyStat" IS NOT NULL)
              )
              OR
              -- Heater systems with external temp < 0
              EXISTS (
                  SELECT 1 FROM "WeatherAndStructure" ws
                  WHERE ws."loc_link" IN (
                      SELECT ls."loc_link" FROM "LightingAndSafety" ls
                      WHERE ls."equipRef" = e."EQUIP_CODE"
                  )
                  AND ws."extTempC" < 0
              )
          )
    ) INTO v_is_critical;

    IF v_is_critical THEN
        RAISE EXCEPTION 'Cannot delete critical equipment: % - This is a safety-critical asset', OLD."EQUIP_CODE";
    END IF;

    RETURN OLD;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION prevent_critical_equipment_delete()
RETURNS TRIGGER AS $$
DECLARE
    v_is_critical BOOLEAN;
BEGIN
    SELECT EXISTS (
        SELECT 1
        FROM "Equipment" e
        JOIN "EquipmentType" et ON e."EquipType" = et."EquipType"
        WHERE e."EQUIP_CODE" = OLD."EQUIP_CODE"
          AND e."EquipType" = 'Safety'
          AND CAST(et."type_indices"->>'safety_idx' AS numeric) > 0.75
          AND (
              EXISTS (
                  SELECT 1 
                  FROM "LightingAndSafety" ls
                  WHERE ls."equipRef" = e."EQUIP_CODE"
                    AND (ls."lifeSupportStat" IS NOT NULL OR ls."O2SupplyStat" IS NOT NULL)
              )
              OR
              EXISTS (
                  SELECT 1
                  FROM "Communication" comm
                  JOIN "Location" loc ON comm."loc_link" = loc."STATION_name"
                  JOIN "WeatherAndStructure" ws ON ws."loc_link" = loc."STATION_name"
                  WHERE comm."equipRef" = e."EQUIP_CODE"
                    AND ws."extTempC" < 0
              )
          )
    ) INTO v_is_critical;

    IF v_is_critical THEN
        RAISE EXCEPTION 'Cannot delete critical equipment: % - This is a safety-critical asset', OLD."EQUIP_CODE";
    END IF;

    RETURN OLD;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER protect_critical_equipment
BEFORE DELETE ON "Equipment"
FOR EACH ROW
EXECUTE FUNCTION prevent_critical_equipment_delete();

